	}
	if s.User.AssignedLocationID == nil || sm.TargetLaboratoryID == nil || *sm.TargetLaboratoryID != *s.User.AssignedLocationID {
		return 0, nil, errOf(403, "laboratory_not_assigned", "this sample is not routed to your laboratory")
	}
	occurredAt := time.Now()
	if t, ok := parseTime(req.OccurredAt); ok {
