	db.Exec(`UPDATE samples SET status='exception', exception=$1 WHERE id=$2`, mustJSON(map[string]any{
		"type": req.ExceptionType, "code": req.ExceptionType, "note": req.Note, "flaggedAt": fmtTime(occurredAt),
	}), sm.ID)
