func checkPlanVersion(j *Journey, expected int) *apiErr {
	if expected > 0 && expected != j.PlanVersion {
		return errOf(409, "stale_plan", "the journey plan has changed; reload it and retry")
	}
	return nil
}

func journeySummaryJSON(j *Journey) map[string]any {
