func handleReportDisruption(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Type       string  `json:"type"`
		LocationID *string `json:"locationId"`
		WorkerID   *string `json:"workerId"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if !contains([]string{"worker", "node", "route", "laboratory", "capacity_pool"}, req.Type) {
		return 0, nil, errOf(400, "invalid_request", "unknown disruption type")
	}
	replanned := 0
	affected := []string{}
	switch req.Type {
	case "worker":
		if req.WorkerID == nil {
			return 0, nil, errOf(400, "invalid_request", "workerId is required")
		}
		db.Exec(`UPDATE users SET available=false WHERE id=$1`, *req.WorkerID)
		rows, _ := db.Query(`SELECT DISTINCT sample_id FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress') AND sample_id IS NOT NULL`, *req.WorkerID)
		if rows != nil {
			for rows.Next() {
				var sid string
				rows.Scan(&sid)
				affected = append(affected, sid)
			}
			rows.Close()
		}
	case "node", "laboratory", "capacity_pool":
		if req.LocationID == nil {
			return 0, nil, errOf(400, "invalid_request", "locationId is required")
		}
		rows, _ := db.Query(`SELECT DISTINCT sample_id FROM assignments WHERE (node_id=$1 OR laboratory_id=$1 OR from_location_id=$1 OR to_location_id=$1) AND status IN ('pending','offered') AND sample_id IS NOT NULL`, *req.LocationID)
		if rows != nil {
			for rows.Next() {
				var sid string
				rows.Scan(&sid)
				affected = append(affected, sid)
			}
			rows.Close()
		}
	case "route":
		rows, _ := db.Query(`SELECT DISTINCT sample_id FROM assignments WHERE status IN ('pending','offered') AND sample_id IS NOT NULL`)
		if rows != nil {
			for rows.Next() {
				var sid string
				rows.Scan(&sid)
				affected = append(affected, sid)
			}
			rows.Close()
		}
	}
	for _, sid := range affected {
		sm, err := loadSample(sid)
		if err != nil || sm.Status == "received" || sm.Status == "cancelled" {
			continue
		}
		if _, aerr := replanSample(sm, "disruption: "+req.Type); aerr == nil {
			replanned++
		}
	}
	recordAudit(s.User.ID, s.ActiveRole, "report_disruption", req.Type, "", true, map[string]any{"replanned": replanned})
	return 201, map[string]any{
		"type":              req.Type,
		"samplesAffected":   len(affected),
		"samplesReplanned":  replanned,
	}, nil
}

func replanForUnavailableLocation(locationID string) {
	rows, err := db.Query(`SELECT DISTINCT sample_id FROM assignments WHERE (node_id=$1 OR laboratory_id=$1 OR from_location_id=$1 OR to_location_id=$1) AND status IN ('pending','offered') AND sample_id IS NOT NULL`, locationID)
	if err != nil {
		return
	}
	defer rows.Close()
	var sids []string
	for rows.Next() {
		var sid string
		rows.Scan(&sid)
		sids = append(sids, sid)
	}
	for _, sid := range sids {
		if sm, err := loadSample(sid); err == nil && sm.Status != "received" && sm.Status != "cancelled" {
			replanSample(sm, "location unavailable")
		}
	}
}

func replanForUnavailableConnection(connectionID string) {
	rows, err := db.Query(`SELECT DISTINCT j.sample_ids FROM journeys j WHERE j.status IN ('planned','in_progress') AND j.connection_ids @> $1::jsonb`, mustJSON([]string{connectionID}))
	if err != nil {
		return
	}
	defer rows.Close()
	var sids []string
	for rows.Next() {
		var raw []byte
		rows.Scan(&raw)
		for _, sid := range strSlice(raw) {
			sids = append(sids, sid)
		}
	}
	for _, sid := range sids {
		if sm, err := loadSample(sid); err == nil && sm.Status != "received" && sm.Status != "cancelled" {
			replanSample(sm, "connection unavailable")
		}
	}
}
