	}
	seedSampleTypes()
	ensureServiceabilitySnapshot()
	ensureInitialAdmin()
}

func resetDB() {
	openDB()
	if _, err := db.Exec(`DROP SCHEMA public CASCADE; CREATE SCHEMA public;`); err != nil {
